#include <stdio.h>
#include "packing_config.h"

static int read_digit(void)
{
    int symbol = getchar();
    if (symbol < '0' || symbol > '9') {
        return -1;
    }
    int tail = getchar();
    return tail == '\n' || tail == EOF ? symbol - '0' : -1;
}

int main(void)
{
    int boxes = read_digit();
    if (boxes < 0) {
        puts("invalid");
        return 1;
    }
    printf("items=%d\n", boxes); /* TODO: use BOX_AMOUNT. */
    return 0;
}

